const input = $input.first().json;
const body = input.body || input;
const message = body.message || body.callback_query?.message;

if (!message) return [{ json: { skip: true } }];

const text = message.text || '';
const chatId = message.chat?.id;
const userId = message.from?.id;
const username = message.from?.username || '';

// Parse commands
let command = null;
let args = '';
if (text.startsWith('/')) {
  const parts = text.split(' ');
  command = parts[0].toLowerCase();
  args = parts.slice(1).join(' ');
}

return [{
  json: {
    chat_id: chatId,
    user_id: userId,
    username: username,
    text: text,
    command: command,
    args: args,
    is_command: !!command
  }
}];

const msg = $input.first().json;
let responseText = '';

switch (msg.command) {
  case '/start':
    responseText = '👋 Welcome to GreeVo Bot!\n\nCommands:\n/status - System status\n/leads - Today\'s new leads\n/pipeline - Pipeline summary\n/seo - SEO overview\n/help - Show commands';
    break;
  case '/status':
    responseText = '__STATUS_QUERY__';
    break;
  case '/leads':
    responseText = '__LEADS_QUERY__';
    break;
  case '/pipeline':
    responseText = '__PIPELINE_QUERY__';
    break;
  case '/seo':
    responseText = '__SEO_QUERY__';
    break;
  case '/help':
    responseText = '📋 *Available Commands:*\n\n/status - System health\n/leads - New leads today\n/pipeline - Sales pipeline\n/seo - SEO metrics\n/help - This message';
    break;
  default:
    responseText = 'Unknown command. Type /help for available commands.';
}

return [{ json: { ...msg, response_text: responseText, needs_query: responseText.includes('__') } }];

const queryResult = $input.first().json;
const msg = $node['Handle Command'].json;
let data;
try { data = JSON.parse(queryResult.result || '{}'); } catch(e) { data = {}; }

let text = '';
switch (data.type) {
  case 'status':
    text = `⚙️ *System Status*\n\n• Workflows (1h): ${data.active_workflows}\n• Errors (1h): ${data.errors_1h}\n• Total Contacts: ${data.total_contacts}\n• Active Deals: ${data.active_deals}`;
    break;
  case 'leads':
    const recent = data.recent || [];
    text = `👥 *Leads Today*\n\n• New Today: ${data.today}\n• Hot Leads: ${data.hot}\n\n*Recent:*\n${recent.map(r => `• ${r.name} (${r.company}) - Score: ${r.score}`).join('\n') || 'None yet'}`;
    break;
  case 'pipeline':
    text = `💰 *Pipeline*\n\n• Value: Rp ${Number(data.total_value).toLocaleString('id-ID')}\n• Deals: ${data.deal_count}\n• Won MTD: Rp ${Number(data.won_mtd).toLocaleString('id-ID')}`;
    break;
  case 'seo':
    text = `🔍 *SEO*\n\n• Keywords: ${data.keywords}\n• Top 10: ${data.top10}\n• Backlinks: ${data.backlinks}`;
    break;
  default:
    text = 'Data not available.';
}

return [{ json: { chat_id: msg.chat_id, text: text } }];
